import{z as s,x as i,o as B,c as p,q as t,j as n,D as A,d as a,s as r,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"工具链与复现规范","description":"","frontmatter":{"title":"工具链与复现规范","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-toolchain-repro.md","filePath":"llm/xai-toolchain-repro.md","lastUpdated":1791413859000}'),d={name:"llm/xai-toolchain-repro.md"};function m(C,E,D,h,c,f){const o=i("Mermaid");return B(),p("div",null,[E[2]||(E[2]=t('<h1 id="工具链与复现规范" tabindex="-1">工具链与复现规范 <a class="header-anchor" href="#工具链与复现规范" aria-label="Permalink to &quot;工具链与复现规范&quot;">​</a></h1><div class="epigraph"><p>前七课每一步都踩在工具链上；可解释性实验比一般 ML 更难复现，因为结论绑定的不只是代码与数据，还有一层特征编号的临时本体论。</p><footer>—— 据 Lieberum et al., 2024（Gemma Scope）与 Templeton et al., 2024 的开放实践整理</footer></div><p><a href="/llm/xai-mechanistic-eval">上一课</a>把机制做成了评测判据。判据要有公信力，前提是任何人能用同样的工具、同样的口径走到同一个结果——这正是可解释性最薄弱的环节。本课写两件事：工具链的分层，以及把前七课散落的口径钉成复现规范。它也是本课程从「方法与场景」走向「边界与收束」前的最后一节工程课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复现可解释性实验有三重困难。<strong>编号不可移植</strong>：换 seed、换宽度、换 checkpoint，特征编号整体作废，「第 1024 号特征」离开它的字典毫无意义。<strong>解释循环依赖解释器</strong>：释义评分随解释器版本漂移，第 2 课压住循环性的协议，换个人跑可能没有。<strong>自由度爆炸</strong>：位点、层号、宽度、架构、稀疏系数、数据量、中心化方式——「同一个 SAE」在这七个自由度下没有定义。</p><p><span class="marginnote">「临时本体论」翻译一下：本体论本是哲学术语，指「一套东西的清单与命名」。特征编号就是这样一套命名——它只对某一次具体训练出来的字典有效，重训一次就整体换名。这和化学元素表完全不同：氧是自然种，换个实验室还是氧；「第 1024 号特征」不是自然种，离开那支字典就是空签。</span></p><p>一般 ML 复现只要 pin 代码与数据；这里还要 pin 一套临时本体论——哪些方向算「找到过」、叫什么名字。缺口因此不是工具不够多，而是层与层之间的接口没有被当成规范来写。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具链四层，每层的接口就是复现规范的一半。</p><p><strong>钩子层。</strong> 前向截获激活、注入干预的库（TransformerLens、nnsight 一类），对齐的是模型实现：模型版本、权重 hash、hook 位点与层号。</p><p><span class="marginnote">「hook（钩子）」是什么：在模型前向计算流经某一层时「拦截」一下——抄走这一刻的激活，或把它换成别的值再放行。类比流水线上装一个观察窗加一只机械手：既能记录每一件过路产品（读激活），也能伸手改一件（干预），后面的工序拿到的是改过的货。</span></p><p><strong>字典层。</strong> 自训用 SAELens 一类训练库，或直接用开放套件——<a href="/llm/gemma-scope">Gemma Scope</a> 把主流开源模型的全层 SAE 放进公共领域，等于把第 1 课的整条工序外包给了公共字典。对齐的是第 1 课的元数据：位点、宽度、架构、平均 \\(L_0\\)、训练 token 量。</p><p><strong>浏览层。</strong> 特征浏览器（Neuronpedia 一类）把「释义 + 最大激活样本 + 转向演示」摆在一起，供人读与跨团队指认。对齐的是第 2 课的报表格式。</p><p><strong>评测层。</strong> 释义评分、干预脚本、特征画像 diff 的执行器。对齐的是解释器版本与判分协议。</p>',14)),(B(),n(l,null,{default:A(()=>[r(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOOK%5B%22%E9%92%A9%E5%AD%90%E5%B1%82%EF%BC%9A%E6%88%AA%E6%BF%80%E6%B4%BB%20%2F%20%E6%B3%A8%E5%B9%B2%E9%A2%84%22%5D%20--%3E%20DICT%5B%22%E5%AD%97%E5%85%B8%E5%B1%82%EF%BC%9A%E8%87%AA%E8%AE%AD%E6%88%96%E5%BC%80%E6%94%BE%20SAE%22%5D%0A%20%20DICT%20--%3E%20BROWSE%5B%22%E6%B5%8F%E8%A7%88%E5%B1%82%EF%BC%9A%E9%87%8A%E4%B9%89%20%2B%20%E6%A0%B7%E6%9C%AC%20%2B%20%E8%BD%AC%E5%90%91%E6%BC%94%E7%A4%BA%22%5D%0A%20%20BROWSE%20--%3E%20EVAL%5B%22%E8%AF%84%E6%B5%8B%E5%B1%82%EF%BC%9A%E8%AF%84%E5%88%86%20%2F%20%E7%94%BB%E5%83%8F%20diff%22%5D%0A%20%20DICT%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%EF%BC%9A%E4%BD%8D%E7%82%B9%20%C2%B7%20%E5%AE%BD%E5%BA%A6%20%C2%B7%20L0%20%C2%B7%20hash%22%5D%0A%20%20EVAL%20--%3E%20SPEC%5B%22%E5%A4%8D%E7%8E%B0%E5%8C%85%20%3D%20%E4%BB%A3%E7%A0%81%20%2B%20%E6%9D%83%E9%87%8D%20%2B%20%E5%85%83%E6%95%B0%E6%8D%AE%20%2B%20%E6%8A%A5%E8%A1%A8%22%5D%0A%20%20META%20--%3E%20SPEC%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"复现锚点为什么是「释义 + 激活样本 + 转向效应」三元组而不是编号：编号在重训里必然变，三元组不依赖具体运行——重训后按语义重新对齐，特征画像 diff 就是在做这件事。这是「临时本体论」的唯一稳定指称方式：特征不是自然种，是字典的函数，指称它的稳定方式只能经过它的证据。",-1)),E[5]||(E[5]=e("p",null,[a("开放套件的机制价值因此不止省算力：公共字典是跨团队的"),e("strong",null,"公共纵轴"),a("。两家实验室各自训字典，比较「谁发现了欺骗特征」无从谈起；都用同一套开放字典，特征指认、缺陷上报、回归追踪才有共同对象。这也是开放生态被当成可解释性基础设施、而不只是福利的原因。")],-1)),(B(),n(l,null,{default:A(()=>[r(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20LA%5B%22%E5%AE%9E%E9%AA%8C%E5%AE%A4%E7%94%B2%EF%BC%9A%E8%87%AA%E8%AE%AD%E5%AD%97%E5%85%B8%20A%22%5D%20--%3E%20AX1%5B%22%E7%BC%96%E5%8F%B7%E5%8F%AA%E5%9C%A8%E5%AD%97%E5%85%B8%20A%20%E9%87%8C%E6%9C%89%E6%84%8F%E4%B9%89%22%5D%0A%20%20LB%5B%22%E5%AE%9E%E9%AA%8C%E5%AE%A4%E4%B9%99%EF%BC%9A%E8%87%AA%E8%AE%AD%E5%AD%97%E5%85%B8%20B%22%5D%20--%3E%20AX2%5B%22%E5%90%8C%E4%B8%80%E6%A6%82%E5%BF%B5%E5%9C%A8%20B%20%E9%87%8C%E6%98%AF%E5%8F%A6%E4%B8%80%E4%B8%AA%E7%BC%96%E5%8F%B7%22%5D%0A%20%20AX1%20--%3E%20NO%5B%22%E3%80%8C%E8%B0%81%E5%8F%91%E7%8E%B0%E4%BA%86%E6%AC%BA%E9%AA%97%E7%89%B9%E5%BE%81%E3%80%8D%E6%97%A0%E4%BB%8E%E6%AF%94%E8%BE%83%22%5D%0A%20%20AX2%20--%3E%20NO%0A%20%20OPEN%5B%22%E5%8F%8C%E6%96%B9%E5%85%B1%E7%94%A8%E5%BC%80%E6%94%BE%E5%85%AC%E5%85%B1%E5%AD%97%E5%85%B8%22%5D%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E7%BC%96%E5%8F%B7%E6%8C%87%E5%90%91%E5%90%8C%E4%B8%80%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20SAME%20--%3E%20YES%5B%22%E6%8C%87%E8%AE%A4%20%2F%20%E7%BC%BA%E9%99%B7%E4%B8%8A%E6%8A%A5%20%2F%20%E5%9B%9E%E5%BD%92%E8%BF%BD%E8%B8%AA%E6%9C%89%E5%85%B1%E5%90%8C%E5%9D%90%E6%A0%87%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">「公共纵轴」类比坐标系：两人各带一把刻度不同的尺子，报出的长度没法对账；约定同一把尺子后，测量才有比较的意义。开放字典就是解释性社区的公尺——它未必是最准的尺，但让「你说的 1024 号」和「我说的 1024 号」第一次指向同一个东西。</span></p><p><span class="marginnote">复现一条特征的最低清单：位点与层号、宽度与膨胀倍数、架构与平均 \\(L_0\\)、激活函数、训练 token 量、checkpoint hash、释义加十条最大激活样本、转向 \\(\\alpha\\) 与效应记录。少任何一项，复现者就是在对另一支透镜——而没人告诉他焦距差多少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规范不能让本体论稳定：字典一更新，旧编号的语义漂移，跨字典的「同一特征」最多是语义近似。私有模型没有公共字典，只有内部纵轴，跨组织的缺陷通报要附带完整复现包才可检验。工具链也不兜底方法错误：口径完全对齐的两个团队，可能一起用同一种带偏差的评分器得出同一个错误结论——复现解决「是不是同一个实验」，不解决「实验对不对」。最后，规范有成本：元数据与报表的完备性是工程税，团队会在进度压力下砍它；把它做成工具的默认输出而不是自觉，是这一课真正的落点。</p><p><span class="marginnote">常见误区：「实验可复现 = 结论正确」。两个团队用同一把刻度偏了的尺子，量出同一个错的数——完全可复现，但都错。复现回答的是「你们做的是不是同一个实验」，对错要靠第 2 课的对照与验收去压。把这两件事混为一谈，会出现「已复现，所以可信」的空担保。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具链四层：钩子、字典、浏览、评测；每层接口即规范的一半。</li><li>复现锚点是「释义 + 激活样本 + 转向效应」三元组，不是特征编号。</li><li>开放字典是跨团队的公共纵轴，缺陷通报与回归追踪都踩在它上面。</li><li>复现保证「同一个实验」，不保证「实验正确」；方法偏差要靠第 2 课的对照压。</li><li>出处：Lieberum et al., 2024（Gemma Scope）；Templeton et al., 2024 的开放与不完备声明；工具名以公开仓库为准。</li></ul>',7))])}const u=s(d,[["render",m]]);export{g as __pageData,u as default};
